from pathlib import Path
p=Path('scripts/build_site.py')
s=p.read_text()
def replace(a,b,count=None):
 global s
 found=s.count(a)
 if not found or count is not None and found!=count: raise ValueError((a,found,count))
 s=s.replace(a,b)
replace('<link rel="stylesheet" href="style.css"><script src="script.js" defer></script>', '<link rel="stylesheet" href="style.css"><link rel="stylesheet" href="depth.css"><script src="script.js" defer></script><script src="depth.js" defer></script>',1)
replace('<body>{header(active)}', '<body class="page-{filename.removesuffix(".html")}">{header(active)}',1)
replace('<section class="partner-band wrap reveal"><div>', '<section class="partner-band wrap" data-depth-scene>{depth_seam("cta", ["strip"])}<div>',1)
replace('<a class="product-image" href=', '<a class="product-image" data-tilt href=',2)
replace('<img src="{p[\'image\']}" width="600"', '<img class="tilt-plane" src="{p[\'image\']}" width="600"',2)
replace('<section class="protein-section" id="protein"', '<section class="protein-section" data-depth-scene id="protein"',1)
replace('<img class="bridge-cluster"', '<img class="bridge-cluster depth-motion" data-depth="28" data-depth-turn="3"',1)
replace('<img class="bridge-single"', '<img class="bridge-single depth-motion" data-depth="-24" data-depth-turn="-5"',1)
replace('<section class="hero"><div', '<section class="hero" data-depth-scene><div',1)
replace('<figure class="hero-art"><img', '<figure class="hero-art"><img class="depth-motion" data-depth="24" data-depth-turn="1"',1)
replace('фирменные курочки"></figure></div></section>', 'фирменные курочки"></figure></div>{depth_seam("hero", ["meatball"])}</section>',1)
replace('<section class="brand-story"><div', '<section class="brand-story" data-depth-scene><div')
replace('<img class="story-mascot"', '<img class="story-mascot depth-motion" data-depth="22" data-depth-turn="2"')
replace('<figure class="detail-visual reveal"><img', '<figure class="detail-visual" data-tilt><img class="tilt-plane"',1)
replace('</div></div></section><section class="section wrap"><div class="section-heading reveal"><h2>А ещё к столу…', '</div></div></section><section class="related-section"><div class="section wrap"><div class="section-heading reveal"><h2>А ещё к столу…',1)
replace('{cards(more)}</div></section>', '{cards(more)}</div></div></section>',1)
replace('<section class="wrap section about-editorial"><figure class="reveal">', '<section class="wrap section about-editorial" data-depth-scene><figure class="reveal editorial-photo">',1)
replace('<section class="brand-story" data-depth-scene><div class="wrap brand-inner"><div><p', '<section class="brand-story" data-depth-scene>{depth_seam("about", ["nugget"])}<div class="wrap brand-inner"><div><p',1)
replace('<div class="city-panel reveal"><p', '<div class="city-panel" data-depth-scene>{depth_seam("shop", ["nugget"])}<p',1)
replace('<section class="partner-hero"><div', '<section class="partner-hero" data-depth-scene>{depth_seam("partner", ["nugget", "strip"])}<div',1)
replace('<section class="contacts-main"><div', '<section class="contacts-main" data-depth-scene><div',1)
replace('<img class="contacts-mascot"', '<img class="contacts-mascot depth-motion" data-depth="16" data-depth-turn="2"',1)
p.write_text(s)